        var lib = loadLib();
        assert.equal(lib.extractCommentBody({ body: { unknown: 1 } }), '{"unknown":1}');
        assert.equal(lib.extractCommentBody({ body: null }), 'null');
        assert.equal(lib.extractCommentBody({ body: 7 }), '7');
    });
