+ */
+function parseAiJson(text) {
+    try {
+        return { value: JSON.parse(text) };
+    } catch (error) {
+        return { error: error };
+    }
+}
+
+/**
+ * Validate expected module analysis structure: core/api/ui booleans and a
+ * string description.
