+function hasValidModuleAnalysisFields(response) {
+    return typeof response.core === 'boolean' &&
+        typeof response.api === 'boolean' &&
+        typeof response.ui === 'boolean' &&
+        typeof response.description === 'string';
+}
+
+/**
