 * @returns {Object} Parsed module analysis or null if invalid
 */
function parseModuleAnalysisResponse(response) {
    // Handle string responses (parse JSON)
    if (typeof response === 'string') {
        var parsed = parseAiJson(response);
        if (parsed.error) {
