                rawThreads.filter(function(t) { return t.threadId; }).length + ' resolve IDs' +
                (inv.census.graphqlUnresolved !== null
                    ? ' — GraphQL census: ' + inv.census.graphqlUnresolved + ' unresolved (arm-rule count)'
                    : ''));
